"use client";
/* Voxel, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Voxel(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("voxel"); }, []);
  return React.createElement("piix-voxel", piixAttrs(props));
}

export default Voxel;
